# 强制租户过滤的记忆检索（伪代码）
def search_memory(query: str, tenant_id: str, user_id: str, top_k: int = 5):
    if not tenant_id or not user_id:
        raise ValueError("缺少租户/用户身份，拒绝检索")  # 架构层面禁止无身份查询

    query_vector = embed(query)
    return vector_store.query(
        vector=query_vector,
        namespace=f"tenant:{tenant_id}",       # 命名空间物理隔离，第一道保险
        filter={"user_id": user_id},           # metadata 过滤，第二道保险
        top_k=top_k,
    )
